// generated by gen_matrix (full carrier composition matrix).
use vehje_bench_carrier as c;
use mockspace_bench_core::{timed_calibrated, FfiBenchCall};
use mockspace_bench_macro::bench_variant;
#[allow(unused_imports)]
use std::sync::OnceLock;

#[bench_variant("carrier_res_tight_stack", sizes = [64, 256, 1024, 4096, 16384])]
fn run<const N: usize>(input: &[u8; N], output: &mut [u8; 8]) -> FfiBenchCall {
    static PREP: OnceLock<c::stackbc::StackProgram> = OnceLock::new(); let sp = PREP.get_or_init(|| { let mut gp = c::GenParams::profile("tight").unwrap(); gp.node_count = N; c::stackbc::compile(&c::generate(&gp)) }); let mut st = vec![0u64; 64]; let mut lo = vec![0u64; sp.num_locals];
    const ITERS: usize = 16;
    // timed_calibrated auto-repeats the run block until it clears the counter's
    // 2048-tick quantization floor (the 24 MHz CNTVCT means small-N regions would
    // otherwise be tens of ticks, collapsing small dispatch deltas into ties);
    // above the floor it degrades to one probe pass. acc is seeded from the prior
    // rep's output byte so the calibrated reps form a dependency chain, which
    // (together with writing `output`, which the harness reads) anchors the whole
    // acc/checksum/interpret chain against DCE and cross-rep hoisting.
    timed_calibrated! { run {
        let mut acc: u64 = output[0] as u64;
        let mut k = 0usize;
        while k < ITERS {
            let seed = input[k % N] as u64 ^ (k as u64);
            c::stackbc::interpret_stack(sp, seed, &mut st, &mut lo); acc ^= c::access::checksum_at(&lo, &sp.out_locals);
            k += 1;
        }
        output.copy_from_slice(&acc.to_le_bytes());
    } }
}
